            prerequisites: [lesson1]);

        var lesson3Checklist = new ChecklistSeed(ChecklistOwnerKind.Lesson, lesson3.Slug,
        [
            "Implement 'Longest Substring Without Repeating Characters' from scratch without checking the solution",
